"""Format already-computed decisions; no scoring, fitting or native execution."""
import json
from .common import DOC


def main():
    m=json.loads((DOC/'METRICS.json').read_text());runs=json.loads((DOC/'RUNS.json').read_text())
    # Preserve full command/error bytes only in the immutable external ledger.
    # This publication-only projection changes no counters, statuses or scores.
    import hashlib
    for event in runs['events']:
        if 'reason' in event:
            reason=event.pop('reason')
            event['reason_sha256']=hashlib.sha256(reason.encode()).hexdigest()
            event['reason_location']='IMMUTABLE_EXTERNAL_ATTEMPT_LEDGER'
    (DOC/'RUNS.json').write_text(json.dumps(runs,indent=2,sort_keys=True)+'\n')
    support=json.loads((DOC/'SUPPORT.json').read_text());coverage=json.loads((DOC/'COVERAGE.json').read_text())
    sections=json.loads((DOC/'SECTIONS.json').read_text())
    rows=['# SCI-MD-RHEOLOGY-010 result','', '**'+m['disposition']+'**. G1 / SOURCE_SCENARIO_CHANGE_ONLY; implemented and executed without retuning.','']
    flags=[d['decision'] for v in m['primary'].values() for d in v['decisions'].values()]
    secondary=[d['decision'] for v in m['secondary'].values() for d in v['decisions'].values()]
    rows += [f"Primary: {flags.count('PASS')} PASS, {flags.count('FAIL')} FAIL, {flags.count('UNRESOLVED')} UNRESOLVED. Secondary: {secondary.count('MATERIAL_MODELED_DELIVERY_CONTRAST')} qualified material, {secondary.count('BELOW_DECLARED_MATERIALITY_BUDGET')} below declared budget, {secondary.count('UNRESOLVED')} unresolved.",'']
    if 'FAIL' in flags:
        consequence='Restrict E2 to its previously qualified cases. No E4/E8 rescue, fitting or threshold change follows.'
    elif flags==['PASS']*24:
        consequence=('E2 remains a candidate for this additional tested spatial scenario, with a demonstrated modeled delivery consequence only in the named qualified cases/outputs.' if 'MATERIAL_MODELED_DELIVERY_CONTRAST' in secondary else
                     'E2 transfers sufficiently for the tested outputs. This perturbation did not establish a material delivery consequence on tested support; it does not justify an arbitrary heterogeneity sweep.' if all(x=='BELOW_DECLARED_MATERIALITY_BUDGET' for x in secondary) else
                     'E2 transfers sufficiently for the tested outputs; secondary materiality remains unresolved in the named outputs. Do not expand the matrix.')
    else:consequence='Transfer remains unresolved for the named metrics and numerical/support limitations. Do not expand the matrix or treat missing evidence as success or failure.'
    rows += [consequence,'', '## All 24 primary decisions','', 'Each E metric is a fraction; core-share/TDS metrics use percentage points. Decisions use unrounded values and strict inequalities. Numerical allowances are empirical sensitivities, not confidence intervals or rigorous continuum bounds. Full fresh components are in [METRICS.json](METRICS.json).','', '| Law/history | Metric | M | u | Budget | Decision |','|---|---|---:|---:|---:|---|']
    for key,v in m['primary'].items():
        for k,d in v['decisions'].items():
            fmt=lambda x:'missing' if x is None else f'{x:.10g}'
            rows.append(f"| {key.replace('SW_WATER_ANCHORED_90C','SW').replace('TR_LINEAR','TR')} | {k} | {fmt(d['value'])} | {fmt(d['u_total'])} | {d['budget']:g} | {d['decision']} |")
    rows += ['', 'Primary allowances pair temporal/axial/SW-property refinements, refine C alone radially while E2 stays fixed, and independently recompute 50-digit arithmetic. CORE share always means inner outlet flow/total flow, even with the annulus faster.','', '## All eight secondary delivery-contrast decisions','', 'NEW annulus-fast C versus OLD core-fast C at the same new B_star; old C supplies path normalization. Magnitudes are modeled differences, not errors against experimental truth. The radial allowance refines BOTH C configurations. Thresholds .01 and .10 pp are declared engineering materiality budgets, not taste limits.','', '| Law/history | Magnitude | M | u | Threshold | Decision |','|---|---|---:|---:|---:|---|']
    for key,v in m['secondary'].items():
        for k,d in v['decisions'].items():rows.append(f"| {key.replace('SW_WATER_ANCHORED_90C','SW').replace('TR_LINEAR','TR')} | {k} | {d['value']:.10g} | {d['u_total']:.10g} | {d['budget']:g} | {d['decision']} |")
    unresolved=[key.replace('SW_WATER_ANCHORED_90C','SW').replace('TR_LINEAR','TR')+' '+metric for key,v in m['secondary'].items() for metric,d in v['decisions'].items() if d['decision']=='UNRESOLVED']
    if unresolved:
        rows += ['', 'Unresolved secondary outputs: '+', '.join(unresolved)+'. Their empirical allowances exceed the frozen 20%-of-threshold ceiling (0.02 pp for fraction TDS). Large nominal magnitudes do not override that eligibility requirement. No refinement, threshold or allowance change is made.']
    rows += ['', '| Law/history | Signed fraction TDS: new C minus old C (pp), fractions 1–5 |','|---|---|']
    for key,v in m['secondary'].items():rows.append('| '+key.replace('SW_WATER_ANCHORED_90C','SW').replace('TR_LINEAR','TR')+' | '+', '.join(f'{x:+.6f}' for x in v['signed_fraction_TDS_new_minus_old_pp'])+' |')
    rows += ['', 'Only qualified material decisions support their named case/output; these secondary results never change primary transfer status. The analytic constant-viscosity 4/7-to-1/13 share change is not evidence for solute materiality. A material C contrast does not prove arbitrarily accurate relative E2 contrast predictions.','', '## Common reference support and coverage','', 'All 36 C variants qualified: nine old and nine new per history. Before any new E2 full launch, the declared Decimal floor_to_1e-9kg(.95*minimum) rule was sealed. One history-specific endpoint serves both laws, every refinement, and both comparison types. Zero origin/first increment, native mass-breakpoint union and conservative five-fraction splitting are retained. Native Q*dt supplies carrier water.','', '| History | B_star (kg) | Old C coverage | New C coverage | New E2 coverage |','|---|---:|---:|---:|---:|']
    for h in ('UP','DOWN'):
        spans=[]
        for label in ('old_C','new_C','new_E2'):
            vals=[x['scored_fraction_of_terminal']*100 for k,x in coverage.items() if k.startswith(label+'_') and '_'+h+'_' in k]
            spans.append(f'{min(vals):.6f}–{max(vals):.6f}%')
        rows.append('| '+h+' | '+support['B_star_kg'][h]+' | '+' | '.join(spans)+' |')
    rows += ['', 'Every terminal mass and individual coverage is in [COVERAGE.json](COVERAGE.json); '+('all traces reach support.' if all(x['reaches_support'] for x in coverage.values()) else 'short-support candidates remain unresolved for affected delivery metrics.')+' The remaining tail is deliberately unscored. Historical 009 support and results are unchanged.','', '## Execution, qualification and corrections','', f"Exactly {runs['actual_native_launches']} native launches: {runs['short_launches']} short + {runs['C_launches']} new C + {runs['E2_launches']} new E2; {runs['qualified_completions']} qualified completions; {runs['failed']} failed native attempts; {runs['startup_failures']} startup failures; {runs['infrastructure_retries']} infrastructure retries. All 18 old C traces/manifests/required fields were reused and reobserved read-only. Historical E2 used below is not new evidence.", '', 'All inherited 009 native admissibility, pressure/clock, conservation, bounds, geometry, actual permeability/zone assignment and final-field aggregation checks passed. The ten shorts include analytical conductance/core-share/discrete-water, serial repeats and radial-interface MPI; analytical relative errors are below 9.55e-12 (limit 1e-6). No new control, solver build or altered source law was needed.', '', 'Preparation initially selected a different zlib after sourcing the generic environment; the wrapper restored receipt-bound solver-library resolution before any native launch. One subsequent MPI preparation failed on a missing decomposition-plugin search path before launching the solver. Its directory/log/event are retained; the auxiliary environment was restored and the two completed shorts reused. No scientific input changed. A test fixture initially requested a binary64 endpoint just outside its summed mass support; its endpoint was corrected before qualification. Static QA required adding the new scientific test to its existing NumPy allowlist. The same scientific freeze received only that G0 hash correction before the one independent audit; original bytes remain externally retained ([QA_CORRECTION.json](QA_CORRECTION.json)). Initial broad QA environment/bookkeeping/live-edit failures and final checks are recorded separately; they are not scientific failures.', '', '## Separate virtual-sectioning diagnostic','', f"[SECTIONING.md](SECTIONING.md) and [SECTIONS.json](SECTIONS.json) report {len(sections['cases'])} stored 30 s base fields, including explicitly historical old E2. Remaining solid solubles, retained dissolved solute and assumed uniform initial dry mass are kept distinct. Actual mesh-volume overlap splits partial cells at 18 and 25 mm conservatively, without beverage-EY anchoring or invented subcell structure.", '', 'The experimental middle and outer cuts share E2’s 14.5–29 mm annulus cell at every axial station. Equal normalized E2 values are a resolution constraint: their contrast is unresolved, even if 010 outlet metrics pass. No initial-region solute provenance or regional outlet-delivery history is inferred from inventory snapshots. Ribes’s 2020 deck and newer Decent summary are one experiment; Pocket Science assay details are not imported into Ribes. McKeon challenges spatial resolution and measurement interpretation, not a numerical target. The wet-puck recovery mapping remains unqualified. No additional native integration was used. The new observer initially rejected native dimensionless `[]` notation; a source-verified parser correction and regression test reused the stored evidence. The original rejected diagnostic output is retained externally (details in SECTIONING.md).', '', '## Identities, review and figures','', 'Scientific Puckworks source `2058d0e947ee9eb92c52d64f6165b810f1fb4732`; production dependency `fc61c4670ec7bf801e40bb391aab16048b8da26b`. Actual accepted executable SHA256 `3de93829850829db53927e5a079a855d1c09922f238a3a330f5d01f32f9eb1fb`; runtime receipt `91917bc53ed84777a7c3eaf9838954bdb947041d8ad3dd0e9fd1e137d7052d5c`. [REUSE.json](REUSE.json) binds exact source, build, tables and native references. [ARTIFACT_RECEIPT.json](ARTIFACT_RECEIPT.json) binds external outputs; full logs, paths, fields, restricted tables and binaries stay external.', '', 'One independent pre-scoring agent audit PASS: [AUDIT.json](AUDIT.json), corrected freeze `518920beb697fc93ea6279018df709dadf7520e45086be499697bbea9a6a27f9`. Final exact-head agent review, protected GitHub approval, external human review and hosted CI are distinct; actual head/tree and CI snapshot are recorded in the PR handoff. Reproduction: [README.md](README.md).', '', 'Figures: [hydraulics/core allocation](hydraulics.svg), [mass-conditioned delivery](delivery.svg), [signed C fraction contrasts](fractions.svg), [support coverage](coverage.svg), [magnitude/allowance versus budget](budgets.svg).', '', '## Claim ceiling and stop','', '**PHYSICAL_VALIDATION = NOT_ESTABLISHED.** This is a source-conditioned synthetic comparison, not real-puck validation. The reversal changes the area-weighted permeability distribution/residence times as well as radial position. TR dilute continuation and industrial-extract transfer, SW water anchoring and 90 C extrapolation remain caveats. No unique lateral mechanism, arbitrary geometry/permeability/history, whole-shot equivalence beyond support, two-state lumped-model, measured-speedup or production-adoption claim follows. Defaults, solver, dependency lock, Puckworks and historical results are preserved. No merge, rescue matrix, laboratory action or successor; stop at the open PR.']
    insertion=rows.index('## Identities, review and figures')
    section_rows=['Stored-field values below are percentages of each section’s reconstructed initial dry coffee mass. They are inventory diagnostics, not assay EY or regional delivered EY. C=64 radial cells; E2=2. Each triple is centre / middle / outer.', '', '| Configuration/model/law/history | Solid depletion (%) | Retained dissolved solute (%) |', '|---|---:|---:|']
    for key,v in sections['cases'].items():
        # JSON keys sort alphabetically; restore physical centre/middle/outer order explicitly.
        ordered=[v['sections'][name] for name in ('centre_0_18mm','middle_18_25mm','outer_25_29mm')]
        triple=lambda field:' / '.join(f'{x[field]:.5f}' for x in ordered)
        section_rows.append('| '+key.replace('_base','').replace('SW_WATER_ANCHORED_90C','SW').replace('TR_LINEAR','TR')+' | '+triple('solid_depletion_percent_initial_dry')+' | '+triple('retained_dissolved_percent_initial_dry')+' |')
    section_rows += ['', f"Available stored cases: {len(sections['cases'])}; missing or invalid: {len(sections['unavailable'])}. Exact compartment masses, conservation residuals, partial-cell counts and unavailable outputs are in SECTIONS.json.", '']
    rows[insertion:insertion]=section_rows
    (DOC/'RESULT.md').write_text('\n'.join(rows)+'\n')

if __name__=='__main__':main()
